    global.getGoogleMapsSearchUrl = function (placeObjOrName, cityLabel) {
        var q = "";
        if (placeObjOrName && typeof placeObjOrName === "object") {
            q = placeObjOrName.googleMapsQuery || (placeObjOrName.name + ", " + (placeObjOrName.location || cityLabel || "Uttar Pradesh"));
        } else {
            q = (placeObjOrName || "") + ", " + (cityLabel || "Uttar Pradesh") + ", India";
        }
        return "https://www.google.com/maps/search/?api=1&query=" + encodeURIComponent(q);
    };

    global.getPlaceDetailsUrl = function (cityKey, placeId) {
        return "place-details.html?city=" + encodeURIComponent(cityKey) + "&id=" + encodeURIComponent(placeId);
    };

    global.startTripFromPlace = function (cityKey, placeId) {
        var meta = global.CITY_META[cityKey] || {};
        var place = (global.PLACES_CATALOG[cityKey] && global.PLACES_CATALOG[cityKey][placeId]) || {};
        var params = new URLSearchParams();
        params.set("openWizard", "true");
        params.set("city", cityKey);
        if (placeId) params.set("placeId", placeId);
        if (place.name) params.set("placeName", place.name);
        if (meta.label) params.set("cityLabel", meta.label);
        window.location.href = "/home.html?" + params.toString();
    };
